  const month = (w) => BO_MONTHS[w] || BO_MONTHS[w.toLowerCase()];
  const date = s.match(/^([А-Яа-я]+),\s*(\d+)\s+([А-Яа-я]+)(.*)$/);
  if (date && day(date[1]) && month(date[3])) {
    const tail = date[4].trim();
    return cap(day(date[1])) + ', ' + date[2] + ' ' + month(date[3]) + (tail ? ' ' + boPhrase(tail) : '');
  }
  const dayNum = s.match(/^([А-Яа-я]+) (\d+)$/);
  if (dayNum && day(dayNum[1])) return cap(day(dayNum[1])) + ' ' + dayNum[2];
  if (day(s)) return cap(day(s));
  if (month(s)) return cap(month(s));
  return s;
}

function boTranslate(root) {
  if (boLang() !== 'en') return;
  const walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walk.nextNode()) nodes.push(walk.currentNode);
  for (const n of nodes) {
    const raw = n.nodeValue;
    const s = raw.trim();
    if (!s || !/[А-Яа-я]/.test(s)) continue;
    const out = boPhrase(s);
    if (out !== s) n.nodeValue = raw.replace(s, out);
  }
  root.querySelectorAll('[title], [aria-label], [placeholder]').forEach((el) => {
    ['title', 'aria-label', 'placeholder'].forEach((a) => {
      const v = el.getAttribute(a);
      if (v && /[А-Яа-я]/.test(v)) el.setAttribute(a, boPhrase(v.trim()));
    });
  });
}

// The widget keeps rendering Bulgarian; this re-runs the swap after every render
// it does, without needing a hook into render() itself. boTranslate only touches
// text containing Cyrillic, so a second pass over its own output changes nothing
// and the observer settles.
let boBusy = false;
const boSweep = () => {
  if (boBusy || boLang() !== 'en') return;
  boBusy = true;
  try { boTranslate(document.body); } catch (e) {} finally { boBusy = false; }
};
new MutationObserver(boSweep).observe(document.body, { childList: true, subtree: true, characterData: true });
setTimeout(boSweep, 0);

